<script setup>
import { ref } from 'vue';
import { Download, Upload, ShieldCheck, DatabaseBackup, Languages, FileSpreadsheet, Info } from '@lucide/vue';
import { state, dispatch, notify, restoreBackup } from '../state';
import { storage, desktop } from '../storage';
import { t, language, date, errorText } from '../i18n';
import { exportInventory, csvText } from '../../core/csv.mjs';
import { BACKUP_LIMIT } from '../../core/files.mjs';
import PageHeader from '../components/PageHeader.vue';
import FormField from '../components/FormField.vue';
import AppDialog from '../components/AppDialog.vue';
import CsvImportDialog from '../components/CsvImportDialog.vue';
import BackupControls from '../components/BackupControls.vue';
const backupControls=ref();
const showImport=ref(false),restore=ref(null),busy=ref(false),error=ref(''),fileInput=ref();
const lastBackup=ref(localStorage.getItem('ricamo-last-backup')||'');
async function setting(key,value){try{await dispatch('settings.save',{[key]:value});notify();}catch(caught){error.value=errorText(caught);}}
async function backup(){busy.value=true;error.value='';try{if(await storage.backup()){lastBackup.value=new Date().toISOString();localStorage.setItem('ricamo-last-backup',lastBackup.value);await backupControls.value?.refresh();notify();}}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function inspect(event){const file=event.target.files?.[0];if(!file)return;busy.value=true;error.value='';try{if(file.size>BACKUP_LIMIT)throw Object.assign(new Error(),{code:'file_too_large'});restore.value=await storage.inspectRestore(await file.text());}catch(caught){error.value=errorText(caught);}finally{busy.value=false;event.target.value='';}}
async function confirmRestore(){busy.value=true;try{await restoreBackup(restore.value.token);restore.value=null;}catch(caught){error.value=errorText(caught);}finally{busy.value=false;}}
async function exportData(type){try{let data;if(type==='inventory')data=exportInventory(state.value,language.value);else{const rows=state.value[type];const headers=type==='movements'?['id','date','kind','materialId','lotId','quantity','unit','before','after','projectId','reason','cost','currency']:type==='projects'?['id','name','technique','status','dueDate','notes','patternId','revisionId','manualPercent','budget','currency']:['id','materialId','quantity','unit','received','status','unitPrice','currency','notes'];data=csvText(headers,rows.map(row=>headers.map(key=>row[key])));}await storage.saveFile({name:`ricamo-${type}.csv`,data});}catch(caught){error.value=errorText(caught);}}
</script>
<template>
  <div class="page"><PageHeader :eyebrow="t('settings')" :title="t('settingsTitle')" />
    <p v-if="error" class="notice error" role="alert">{{ error }}</p>
    <div class="settings-grid"><section class="panel"><div class="panel-heading"><h2>{{ t('preferences') }}</h2><Languages :size="20" class="muted" /></div><div class="panel-body"><div class="form-grid"><FormField :label="t('language')" wide v-slot="{id}"><select :id="id" :value="state.settings.language" @change="setting('language',$event.target.value)"><option value="it">Italiano</option><option value="en">English</option></select></FormField><FormField :label="t('currency')" v-slot="{id}"><select :id="id" :value="state.settings.currency" @change="setting('currency',$event.target.value)"><option v-for="currency in ['EUR','GBP','USD','CHF','CAD','AUD','JPY','BRL']" :key="currency">{{ currency }}</option></select></FormField><FormField :label="t('paper')" v-slot="{id}"><select :id="id" :value="state.settings.paper" @change="setting('paper',$event.target.value)"><option value="a4">A4</option><option value="letter">Letter</option></select></FormField></div></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('backup') }}</h2><DatabaseBackup :size="20" class="muted" /></div><div class="panel-body"><p class="field-help">{{ t('backupHelp') }}</p><div class="stat-row"><span>{{ t('lastBackup') }}</span><span>{{ lastBackup?date(lastBackup):t('never') }}</span></div><div class="actions" style="margin-top:18px;flex-wrap:wrap"><button class="button primary" :disabled="busy" @click="backup"><Download :size="16" />{{ t('createBackup') }}</button><button class="button" :disabled="busy" @click="fileInput.click()"><Upload :size="16" />{{ t('restoreBackup') }}</button></div><input ref="fileInput" type="file" accept=".ricamobackup" class="sr-only" :aria-label="t('restoreBackup')" @change="inspect" /><p v-if="desktop" class="field-help" style="margin-top:16px">{{ t('automaticBackupHelp') }}</p><BackupControls v-if="desktop" ref="backupControls" /></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('data') }}</h2><FileSpreadsheet :size="20" class="muted" /></div><div class="panel-body"><p class="field-help">{{ t('importHelp') }}</p><div class="actions" style="margin:18px 0;flex-wrap:wrap"><button class="button primary" @click="showImport=true"><Upload :size="16" />{{ t('importCsv') }}</button><button class="button" @click="exportData('inventory')"><Download :size="16" />{{ t('exportCsv') }}</button></div><div class="actions" style="flex-wrap:wrap"><button v-for="type in ['movements','projects','purchases']" :key="type" class="button small" @click="exportData(type)">{{ t('export') }} · {{ t(type==='movements'?'history':type==='purchases'?'shopping':type) }}</button></div></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('about') }}</h2><Info :size="20" class="muted" /></div><div class="panel-body"><h3 style="font-family:Georgia,serif;font-size:25px;font-weight:400">Ricamo <span class="muted" style="font:12px 'Segoe UI',sans-serif">0.1.0</span></h3><p class="notice"><ShieldCheck :size="20" />{{ t('privacy') }}</p><p class="field-help">{{ t('colorAttribution') }}</p><p class="field-help" style="margin-top:12px">Vue · Electron · SQLite · jsPDF · Lucide</p><p v-if="!desktop" class="notice warning" style="margin-top:16px">{{ t('browserPreviewHelp') }}</p></div></section></div>
    <CsvImportDialog v-if="showImport" @close="showImport=false" />
    <AppDialog v-if="restore" :title="t('restoreBackup')" :busy="busy" @close="restore=null"><p v-if="error" class="notice error" role="alert">{{ error }}</p><p class="notice warning">{{ t('restoreWarning') }}</p><div class="stat-row"><span>{{ t('date') }}</span><strong>{{ date(restore.createdAt) }}</strong></div><div v-for="(value,key) in restore.summary" :key="key" class="stat-row"><span>{{ t(key==='attachments'?'files':key) }}</span><strong>{{ value }}</strong></div><template #footer><button class="button" :disabled="busy" @click="restore=null">{{ t('cancel') }}</button><button class="button primary" :disabled="busy" @click="confirmRestore">{{ t('restoreConfirm') }}</button></template></AppDialog>
  </div>
</template>
